from hypothesis import given, settings, assume
from hypothesis import strategies as st
import math

def test_pbt(fn):
    @given(st.integers(min_value=1, max_value=10000))
    @settings(max_examples=100)
    def _test(n):
        result = fn(n)

        # Property 1: Output type is always boolean
        assert isinstance(result, bool)

        # Property 2: Idempotency - calling twice gives same result
        assert fn(n) == result

        # Property 3: Relationship with primality check
        # If a number has a divisor in range [2, sqrt(n)], it's not prime (except n=1)
        has_divisor = False
        if n == 1:
            has_divisor = True
        else:
            for i in range(2, int(math.sqrt(n)) + 1):
                if n % i == 0:
                    has_divisor = True
                    break

        # For n > 1: if has_divisor is True, result should be True
        # For n == 1: result should be True
        if has_divisor:
            assert result == True

        # Property 4: Powers of primes greater than prime^1 are not prime
        # If n is a perfect square > 1, it must not be prime
        sqrt_n = int(math.sqrt(n))
        if sqrt_n * sqrt_n == n and n > 1:
            assert result == True

    _test()
